import heapq

def match(orders):
    book = {}  # id -> {'side','price','qty','seq'}
    buy_heap = []   # entries: (-price, seq, id)
    sell_heap = []  # entries: (price, seq, id)
    seq = 0
    trades = []

    def clean(heap):
        while heap and (heap[0][2] not in book or book[heap[0][2]]['qty'] <= 0):
            heapq.heappop(heap)

    for order in orders:
        typ = order[0]

        if typ == 'cancel':
            oid = order[1]
            if oid in book:
                book[oid]['qty'] = 0
            continue

        if typ == 'market':
            _, oid, side, qty = order
            price = None
        else:
            _, oid, side, price, qty = order

        remaining = qty

        if side == 'buy':
            opp = sell_heap
        else:
            opp = buy_heap

        while remaining > 0:
            clean(opp)
            if not opp:
                break
            top = opp[0]
            if side == 'buy':
                top_price = top[0]
                if price is not None and top_price > price:
                    break
            else:
                top_price = -top[0]
                if price is not None and top_price < price:
                    break

            oid2 = top[2]
            resting = book[oid2]
            trade_qty = min(remaining, resting['qty'])

            if side == 'buy':
                trades.append([oid, oid2, top_price, trade_qty])
            else:
                trades.append([oid2, oid, top_price, trade_qty])

            remaining -= trade_qty
            resting['qty'] -= trade_qty

            if resting['qty'] == 0:
                heapq.heappop(opp)
            # if resting still has qty, remaining must be 0, loop will end

        if typ == 'limit' and remaining > 0:
            seq += 1
            book[oid] = {'side': side, 'price': price, 'qty': remaining, 'seq': seq}
            if side == 'buy':
                heapq.heappush(buy_heap, (-price, seq, oid))
            else:
                heapq.heappush(sell_heap, (price, seq, oid))
        # ioc/market: discard remainder (do nothing)

    return trades

